    ui.instruction.textContent = 'En la barra 1, agarrá las cinco. En la última, cerrá el remate.';
  } else {
    ui.promptLabel.textContent = state.mode === 'esdrujulas' ? 'CONCEPTO · ACENTO EN LA ANTEPENÚLTIMA' : 'CONCEPTO · DOBLE TEMPO';
