886:   function scheduleClick(time, accented) {
887:     if (!state.audio || state.audio.state !== 'running') return;
888:     try {
889:       const oscillator = state.audio.createOscillator();
890:       const gain = state.audio.createGain();
891:       const start = state.audio.currentTime + Math.max(0, time - performance.now()) / 1000;
892:       oscillator.type = 'sine';
893:       oscillator.frequency.value = accented ? 880 : 590;
894:       gain.gain.setValueAtTime(0.0001, start);
895:       gain.gain.exponentialRampToValueAtTime(accented ? 0.11 : 0.055, start + 0.004);
896:       gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.045);
897:       oscillator.connect(gain);
898:       gain.connect(state.audio.destination);
899:       oscillator.start(start);
900:       oscillator.stop(start + 0.05);
901:       oscillator.onended = () => { oscillator.disconnect(); gain.disconnect(); };
902:     } catch (_) {
903:       // A missed sound must not stop the visual beat scheduler.
904:     }
905:   }
