933:   function parseYouTubeUrl(value) {
934:     const raw = String(value || '').trim();
935:     if (!raw || raw.length > 2048) return null;
936:     let url;
937:     try {
938:       url = new URL(/^[a-z][a-z\d+.-]*:/i.test(raw) ? raw : `https://${raw}`);
939:     } catch (_) {
940:       return null;
941:     }
942:     if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) return null;
943:     const host = url.hostname.toLowerCase().replace(/\.$/, '');
944:     const isYoutube = host === 'youtube.com' || host.endsWith('.youtube.com');
